  function needRows(phone) { return NEED.map(function (r) { return '<div class="g-need"' + (phone ? ' style="grid-template-columns:auto minmax(0,1fr) auto"' : "") + ">" + gi(r[0]) + "<div><b>" + r[1] + "</b><small>" + r[2] + "</small></div>" + (r[3] === "Draft" ? st("Draft") : prob("1 problem")) + (phone ? "" : btn("Open")) + "</div>"; }).join(""); }
  function needStrip() { return '<div style="display:grid;grid-template-columns:auto minmax(0,1fr) minmax(0,1fr);gap:22px;align-items:center;padding:2px 14px;border:1px solid color-mix(in srgb,var(--caution) 45%,var(--line-strong));box-shadow:inset 3px 0 0 var(--caution)"><span class="e-eb" style="color:var(--caution-text)">Needs you · 2</span>' + needRows().replace(/class="g-need"/g, 'class="g-need" style="box-shadow:none;grid-template-columns:auto minmax(0,1fr) auto auto"') + "</div>"; }
